  str_draw_card_pool_detail_sub_desc1_1 = "การอัญเชิญนี้<color=#ffbb00>จำกัดเฉพาะผู้เล่นใหม่เท่านั้น</color> โดยคุณจะได้อัญเชิญในราคาที่ต่ำกว่าการอัญเชิญปกติ คุณสามารถอัญเชิญได้ <color=#ffbb00>21</color> ครั้ง (รวมครั้งแรกในโหมดฝึก) หลังจากอัญเชิญครบ 21 ครั้ง อีเวนต์อัญเชิญนี้จะสิ้นสุดลง\n\nการอัญเชิญ <color=#ffbb00>11</color> ครั้งแรกในช่วงอีเวนต์อัญเชิญนี้การันตีว่าคุณจะได้รับออโรเรียน 5 ดาวอย่างน้อยหนึ่งราย โอกาสที่คุณจะได้รับออโรเรียน 6 ดาวจากการอัญเชิญ 20 ครั้งแรกจะเท่ากับการอัญเชิญปกติ (ตามที่แสดงด้านล่าง) นอกจากนี้ไม่ว่าคุณจะได้รับออโรเรียน 6 ดาวจากการอัญเชิญ 20 ครั้งแรกหรือไม่ การอัญเชิญ<color=#ffbb00>ครั้งที่ 21</color> การันตีว่าคุณจะได้รับหนึ่งในออโรเรียนระดับเริ่มต้น 6 ดาวที่คัดสรรมาเป็นพิเศษ (<color=#ffbb00>นิคินิส กรอนรู เอซี่ หรือซาริเอล</color>)",
  str_draw_card_pool_detail_sub_desc1_2 = "ออโรเรียนที่สามารถอัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nชาโรนา/ซาริเอล/ราฟาเอล/คอนนอลลี/คารอน/เอซี่/วิกตอเรีย/โจนา/นิคินิส/กาบริเอล/มิการ์ด/มิคาเอล/กรอนรู/อิริดอน/วราธ\nออโรเรียน 5 ดาว: 9.5%\nโคแร็กซ์/บาร์ตัน/เคลเคน/ฟิลิชี/โนอาห์/ไฮแดรด/เบนนี่กับคุโระ/เรจินา/เฟาสต์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/อาเรีย/แพกต์/ซิคาเร/ลูอิส/โอดี/คุสคูตา/เดย์นา/ชวาตส์/เนเมซิส/เบเวอร์ลี/คีตติง/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nพาโซโล่/เจน/คุมะกับเพนจี้/มิสบลังค์/มิเชนนี/โคลอี้/คอนสแตนติน/แพตตี้กับแพตซี่/โจแอนนี บูม/อลิซ/บร็อค/เนลส์/แชนดรา/ซิลวา/เลสเตอร์/โจลา/เวนดี้/ยูริอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟกา\nออโรเรียน 3 ดาว: 55.5%\nเซลูซิด/โซยา/ไวท์ดวาร์ฟ/คอร์กอน/ซอร์คกับเบคค์/เจ้าจิ๋ว/เปปี/ริค เลื่อยไฟฟ้า/โจมู/โคลเวอร์/โอฟินา/โดฟ/ลีอาห์/แองเจิล/ยูนิเมต/เอโฮะ/เอมี่",
  str_draw_card_pool_detail_sub_desc1_3 = "ไม่ว่าจะได้รับออโรเรียนมาด้วยวิธีใดก็ตาม (รวมถึงแต่ไม่จำกัดเพียง อัญเชิญ แลกที่ร้านค้า และแจกฟรี) ออโรเรียนที่ซ้ำจะถูกแปลง\nออโรเรียน 6 ดาว: ทุกครั้งที่คุณได้รับตัวละคร 6 ดาวซ้ำ ตัวละครจะถูกแปลงเป็นโซลแอมเบอร์ x1 สำหรับตัวละครนั้น, ฮาร์ทสโตนอเนกประสงค์ x200 และอัญมณีดาวจรัสแสง x20 เมื่อได้รับออโรเรียนซ้ำครั้งที่ 1 จะได้รับเพชรแอสทรัลเพิ่ม x10, ได้รับออโรเรียนซ้ำครั้งที่ 2 จะได้รับเพชรแอสทรัลเพิ่ม x20, ได้รับออโรเรียนซ้ำครั้งที่ 3 จะได้รับเพชรแอสทรัลเพิ่ม x20, ได้รับออโรเรียนซ้ำครั้งที่ 4 จะได้รับเพชรแอสทรัลเพิ่ม x30, ได้รับออโรเรียนซ้ำครั้งที่ 5 เป็นต้นไป จะได้รับเพชรแอสทรัลเพิ่ม x50\nออโรเรียน 5 ดาว: ทุกครั้งที่คุณได้รับตัวละคร 5 ดาวซ้ำ ตัวละครจะถูกแปลงเป็นโซลแอมเบอร์ x1 สำหรับตัวละครนั้น, ฮาร์ทสโตนอเนกประสงค์ x100 และอัญมณีดาวจรัสแสง x5 เมื่อได้รับออโรเรียนซ้ำครั้งที่ 1 จะได้รับเพชรแอสทรัลเพิ่ม x1, ได้รับออโรเรียนซ้ำครั้งที่ 2 จะได้รับเพชรแอสทรัลเพิ่ม x1, ได้รับออโรเรียนซ้ำครั้งที่ 3 จะได้รับเพชรแอสทรัลเพิ่ม x2, ได้รับออโรเรียนซ้ำครั้งที่ 4 จะได้รับเพชรแอสทรัลเพิ่ม x2, ได้รับออโรเรียนซ้ำครั้งที่ 5 เป็นต้นไป จะได้รับเพชรแอสทรัลเพิ่ม x3\nออโรเรียน 4 ดาว: ทุกครั้งที่คุณได้รับตัวละคร 4 ดาวซ้ำ ตัวละครจะถูกแปลงเป็นโซลแอมเบอร์ x1 สำหรับตัวละครนั้น, ฮาร์ทสโตนอเนกประสงค์ x50 และอัญมณีดาว x25\nออโรเรียน 3 ดาว: ทุกครั้งที่คุณได้รับตัวละคร 3 ดาวซ้ำ ตัวละครจะถูกแปลงเป็นฮาร์ทสโตนอเนกประสงค์ x50 และอัญมณีดาว x10",
  str_draw_card_pool_name_10001 = "อัญเชิญตัวหลัก",
  str_draw_card_pool_des_10001 = "อัญเชิญ 10 ครั้งแรก การันตีออโรเรียน 5 ดาว",
  str_draw_card_pool_title_10001_1 = "อัญเชิญตัวหลัก",
  str_draw_card_pool_title_10001_2 = "นอกเหนือจากออโรเรียนที่แสดงอยู่นี้ ยังมีออโรเรียนระดับดาวสูงอีกมากมาย",
  str_draw_card_pool_detail_title_10001 = "ข้อมูลอัญเชิญตัวหลัก",
  str_draw_card_pool_detail_sub_desc10001_1 = "การอัญเชิญตัวหลักนั้น<color=#ffbb00>เปิดถาวร</color> และคุณสามารถใช้สตาร์แฟลร์เพื่ออัญเชิญ\n\nโอกาสเริ่มต้นที่จะได้รับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ <color=#ffbb00>2%</color> หากคุณไม่ได้รับออโรเรียน 6 ดาวหลังจากอัญเชิญ <color=#ffbb00>50</color> ครั้งติดต่อกัน โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color> หากคุณไม่ได้รับออโรเรียน 6 ดาวจากการอัญเชิญครั้งนี้ โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color> เป็นต้น เมื่อคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> ไปเรื่อย ๆ จนกว่าจะถึง <color=#ffbb00>100%</color> หลังจากได้รับออโรเรียน 6 ดาวแล้ว โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น <color=#ffbb00>2%</color>\n\nหมายเหตุ: การเพิ่มโอกาสได้รับออโรเรียน 6 ดาวจากการอัญเชิญตัวหลักเป็นคนละส่วนกันกับการเพิ่มโอกาสในฟังก์ชันอัญเชิญจำกัดเวลา เช่น หากโอกาสได้รับออโรเรียน 6 ดาวจากการอัญเชิญตัวหลักพื้นฐานเพิ่มเป็น <color=#ffbb00>7%</color> การเพิ่มขึ้นนี้จะไม่มีผลกับการอัญเชิญจำกัดเวลาทั้งหมด และในทางกลับกันก็เป็นเช่นเดียวกัน",
  str_draw_card_pool_detail_sub_desc10001_2 = "<color=#ffbb00>อัตราออโรเรียน:</color>\nออโรเรียน 6 ดาว: 2.0%\nออโรเรียน 5 ดาว: 9.5%\nออโรเรียน 4 ดาว: 33.0%\nออโรเรียน 3 ดาว: 55.5%",
  str_draw_card_pool_detail_sub_desc10002_2 = "ออโรเรียนที่สามารถอัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nอูริเอล/คาร์ลีน/ชาโรนา/ซาริเอล/ราฟาเอล/คอนนอลลี/คารอน/เอซี่/วิกตอเรีย/โจนา/นิคินิส/กาบริเอล/มิการ์ด/มิคาเอล/กรอนรู/อิริดอน/วราธ\nออโรเรียน 5 ดาว: 9.5%\nโคแร็กซ์/บาร์ตัน/เคลเคน/ฟิลิชี/โนอาห์/ไฮแดรด/เบนนี่กับคุโระ/เรจินา/เฟาสต์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/อาเรีย/แพกต์/ซิคาเร/ลูอิส/โอดี/คุสคูตา/เดย์นา/ชวาตส์/เนเมซิส/เบเวอร์ลี/คีตติง/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nเจน/คุมะกับเพนจี้/มิสบลังค์/มิเชนนี/โคลอี้/คอนสแตนติน/แพตตี้กับแพตซี่/โจแอนนี บูม/อลิซ/บร็อค/เนลส์/แชนดรา/ซิลวา/เลสเตอร์/โจลา/เวนดี้/ยูริอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟกา\nออโรเรียน 3 ดาว: 55.5%\nเซลูซิด/โซยา/ไวท์ดวาร์ฟ/คอร์กอน/ซอร์คกับเบคค์/เจ้าจิ๋ว/เปปี/ริค เลื่อยไฟฟ้า/โจมู/โคลเวอร์/โอฟินา/โดฟ/ลีอาห์/แองเจิล/ยูนิเมต/เอโฮะ/เอมี่",
