  str_draw_card_pool_detail_sub_desc60014_1 = "การอัญเชิญเอ็กซ์คลูซีฟนี้มีออโรเรียนพิเศษจำกัดเวลา จะเปิดเฉพาะในช่วงเวลาที่ระบุ และสามารถใช้สตาร์แฟลร์พิเศษอัญเชิญได้ ออโรเรียนสำหรับแบนเนอร์การอัญเชิญนี้คือออโรเรียน 6 ดาว <color=#ffbb00>ไรน์ฮาร์ต</color> เมื่ออัญเชิญออโรเรียน 6 ดาว คุณจะมีโอกาส 50% ที่จะได้รับ <color=#ffbb00>ไรน์ฮาร์ต</color> ตัวละครนี้จะไม่ปรากฏในการอัญเชิญอื่น\n\nรายละเอียดกฎการอัญเชิญเอ็กซ์คลูซีฟดังนี้:\n\n- ออโรเรียน 5 ดาวจะได้รับการรับประกันภายในการอัญเชิญ 10 ครั้งแรกของคุณ- ออโรเรียนนี้สามารถรับสมัครได้เฉพาะจาก <color=#ffbb00>การสมัครที่มีอย่างเดียว</color> และจะไม่ถูกเพิ่มเข้าไปในรายการของตัวละครที่สามารถได้รับในรูปแบบการสมัครอื่น ๆ\n\n- กลไกการเพิ่มความน่าจะเป็นของออโรเรียน 6 ดาว: ความน่าจะเป็นเริ่มต้นในการได้รับออโรเรียน 6 ดาวจากการสมัครนี้คือ <color=#ffbb00>2%</color> หากคุณไม่สามารถสมัครออโรเรียน 6 ดาวหลังจาก <color=#ffbb00>50</color> การสมัครติดต่อกัน ความน่าจะเป็นในการได้รับออโรเรียน 6 ดาวในครั้งสมัครถัดไปของคุณจะเพิ่มขึ้นจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color>. ถ้าคุณยังไม่สามารถรับสมัครออโรเรียน 6 ดาวได้ โอกาสในการได้รับออโรเรียน 6 ดาวในครั้งถัดไปของคุณจะเพิ่มขึ้นจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color> และเรื่อย ๆ ไป ทุกครั้งที่คุณไม่สามารถรับสมัครออโรเรียน 6 ดาวได้ โอกาสในการได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> จนถึง <color=#ffbb00>100%</color> หลังจากได้รับออโรเรียน 6 ดาว โอกาสในการได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น <color=#ffbb00>2%</color> \n\n- กลไกการรับประกัน: ในการอัญเชิญเอ็กซ์คลูซีฟ ถ้าออโรเรียน 6 ดาวที่ได้รับใน <color=#ffbb00>2</color> ครั้งติดกันไม่ใช่ออโรเรียน 6 ดาวที่เสนอพิเศษในการอัญเชิญนี้ ออโรเรียน 6 ดาวตัวต่อไปที่ได้รับจากการอัญเชิญนี้<color=#ffbb00>รับประกัน</color>ว่าจะเป็นออโรเรียน 6 ดาวที่เสนอพิเศษ ทุกครั้งที่ได้รับออโรเรียน 6 ดาวที่เสนอพิเศษ ระบบการันตีจะรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: ความน่าจะเป็นที่เพิ่มขึ้นและระบบการันตีของการอัญเชิญเอ็กซ์คลูซีฟนี้เป็นอิสระจากความน่าจะเป็นที่เพิ่มขึ้นและระบบการันตีของการอัญเชิญประเภทอื่น ๆ ความน่าจะเป็นที่เพิ่มขึ้นและกลไกการรับประกันของการรับสมัครแบบพิเศษนี้จะใช้ได้เฉพาะในช่วงเวลานี้เท่านั้น และจะไม่ถูกนำไปใช้ในการรับสมัครแบบพิเศษครั้งถัดไป",
  str_draw_card_pool_name_60002 = "อัญเชิญเอ็กซ์คลูซีฟแสงกระจ่างจุดประกาย",
  str_draw_card_pool_title_60002_1 = "แสงกระจ่างจุดประกาย",
  str_draw_card_pool_title_60002_2 = "เพิ่มโอกาสได้รับ ไรน์ฮาร์ต ในช่วงอีเวนต์!",
  str_draw_card_pool_detail_title_60002 = "ข้อมูลอัญเชิญจำกัดเวลา แสงกระจ่างจุดประกาย",
  str_draw_card_pool_detail_sub_desc60002_1 = "การอัญเชิญเอ็กซ์คลูซีฟนี้จะเปิดในเวลาจำกัดในช่วงที่กำหนดเท่านั้น สามารถใช้สตาร์แฟลร์พิเศษอัญเชิญได้ โดยจะมีออโรเรียนจำกัดเวลาแบบเอ็กซ์คลูซีฟอยู่ภายใน ซึ่งออโรเรียนในครั้งนี้คือ ออโรเรียน 6 ดาว \"ไรน์ฮาร์ต\" เมื่ออัญเชิญออโรเรียน 6 ดาว คุณมีโอกาส 50% ที่จะได้รับ <color=#ffbb00>ไรน์ฮาร์ต</color> และตัวละครนี้จะไม่ปรากฏในการอัญเชิญอื่น\n\nรายละเอียดกติกาการอัญเชิญเอ็กซ์คลูซีฟมีดังนี้:\n\n- การันตีออโรเรียน 5 ดาวภายในการอัญเชิญ 10 ครั้งแรก\n\n- ออโรเรียนนี้จะอัญเชิญได้เฉพาะใน<color=#ffbb00>การอัญเชิญเอ็กซ์คลูซีฟ</color>เท่านั้น และจะไม่นำไปเพิ่มในการอัญเชิญประเภทอื่น ออโรเรียนเอ็กซ์คลูซีฟ<color=#ffbb00>ไรน์ฮาร์ต</color>จะไม่สามารถรับได้ด้วยวิธีการอื่นหลังจากการอัญเชิญนี้สิ้นสุดลงจนถึงวันที่ <color=#ffbb00>31 ธันวาคม 2022</color> หลังจากสิ้นสุดช่วงเวลานี้แล้ว โปรดติดตามประกาศอย่างเป็นทางการสำหรับรายละเอียดการอัญเชิญครั้งต่อไป\n\n- ระบบเพิ่มโอกาสออโรเรียน 6 ดาว: โอกาสเริ่มต้นที่จะได้รับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ <color=#ffbb00>2%</color> หากคุณอัญเชิญไม่ได้ออโรเรียน 6 ดาวหลังจากอัญเชิญ <color=#ffbb00>50</color> ครั้งติดต่อกัน โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color> หากคุณยังคงไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color>เป็นต้น เมื่อคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> ไปเรื่อย ๆ จนกว่าจะถึง <color=#ffbb00>100%</color> หลังจากได้รับออโรเรียน 6 ดาวแล้ว โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น <color=#ffbb00>2%</color>\n\n- ระบบการันตี: ในการอัญเชิญเอ็กซ์คลูซีฟ ถ้าออโรเรียน 6 ดาวที่ได้รับใน <color=#ffbb00>2</color> ครั้งติดกันไม่ใช่ออโรเรียน 6 ดาวที่เสนอพิเศษในการอัญเชิญนี้ ออโรเรียน 6 ดาวตัวต่อไปที่ได้รับจากการอัญเชิญนี้จะเป็นออโรเรียน 6 ดาวที่เสนอพิเศษ<color=#ffbb00>อย่างแน่นอน</color> ทุกครั้งที่ได้รับออโรเรียน 6 ดาวที่เสนอพิเศษ ระบบการันตีจะรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: โอกาสที่เพิ่มขึ้นและระบบการันตีของการอัญเชิญเอ็กซ์คลูซีฟจะไม่เกี่ยวข้องกับโอกาสที่เพิ่มขึ้นและระบบการันตีของการอัญเชิญประเภทอื่น โดยจะมีผลในช่วงนี้เท่านั้นและจะไม่ทบไปยังการอัญเชิญเอ็กซ์คลูซีฟครั้งต่อไป",
  str_draw_card_pool_detail_sub_desc60002_2 = "ในช่วงอีเวนต์อัญเชิญจำกัดเวลาแสงกระจ่างจุดประกาย โอกาสได้รับออโรเรียนต่อไปนี้จะเพิ่มขึ้น\nเมื่ออัญเชิญออโรเรียน 6 ดาว มีโอกาส <color=#ffbb00>50%</color> ที่จะได้รับ<color=#ffbb00>ไรน์ฮาร์ต</color>\n\n\nออโรเรียนที่สามารถอัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nไรน์ฮาร์ต/ไจลส์/เลนอร์/แอเชอร์/เหยา/อาเมะโมริ/รินเนะ/ฟลอรีน/รูบี้/เชอวาน/โนวิโอ/เฮดี้/เบเธล/ลุค/พาโลม่า/แกรม/เรวี่/สโมกกี้/เฟลอร์/เบริล/ฮิอิโระ/\nซินซา/อีฟ/อูริเอล/คาร์ลีน/ชาโรนา/ซาริเอล/ราฟาเอล/คอนนอลลี/คารอน/เอซี่/วิกตอเรีย/โจนา/นิคินิส/กาบริเอล/มิการ์ด/มิคาเอล/กรอนรู/อิริดอน/วราธ\nออโรเรียน 5 ดาว: 9.5%\nรอย/คายาโนะ/เอริก้า/โรบิน/คอร์ดี้/นาโรเซล/เจเนวีฟ/ทาคิ/โคแร็กซ์/บาร์ตัน/เคลเคน/ฟิลิชี/โนอาห์/ไฮแดรด/เบนนี่กับคุโระ/เรจินา/เฟาสต์/แม็กกี้/\nอีสต์วาน/บาร์บาร่า/ลีโอนา/อาเรีย/แพกต์/ซิคาเร/ลูอิส/โอดี/คุสคูตา/เดย์นา/ชวาตส์/เนเมซิส/เบเวอร์ลี/คีตติง/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nฮาชิ & กิน/ทวีตตี้/พาโซโล่/เจน/คุมะกับเพนจี้/มิสบลังค์/มิเชนนี/โคลอี้/คอนสแตนติน/แพตตี้กับแพตซี่/โจแอนนี บูม/อลิซ/บร็อค/เนลส์/แชนดรา/\nซิลวา/เลสเตอร์/โจลา/เวนดี้/ยูริอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟกา\nออโรเรียน 3 ดาว: 55.5%\nเซลูซิด/โซยา/ไวท์ดวาร์ฟ/คอร์กอน/ซอร์คกับเบคค์/เจ้าจิ๋ว/เปปี/ริค เลื่อยไฟฟ้า/โจมู/โคลเวอร์/โอฟินา/โดฟ/ลีอาห์/แองเจิล/ยูนิเมต/เอโฮะ/เอมี่",
