  str_draw_card_pool_title_60010_1 = "ดาวนำโชค",
  str_draw_card_pool_title_60010_2 = "เพิ่มโอกาสในการรับสมัครโกลดี้ในช่วงเวลากิจกรรม!",
  str_draw_card_pool_detail_title_60010 = "ข้อมูลการรับสมัครงานพิเศษของ Lucky Star",
  str_draw_card_pool_detail_sub_desc60010_1 = "การสรรหาพิเศษนี้จะมีให้ใช้งานเฉพาะระยะเวลาจำกัดในช่วงเวลาที่ระบุ สามารถใช้ Star Flares พิเศษในการสรรหาจากกลุ่มนี้ซึ่งรวมถึง Aurorian พิเศษและจำกัดเวลา สำหรับแบนเนอร์สรรหาครั้งนี้คือ Aurorian 6 ดาว Goldie ในการสรรหา Aurorian 6 ดาว คุณจะมีโอกาส 50% ในการสรรหา <color=#ffbb00>Goldie</color> ตัวละครนี้จะไม่ปรากฏในการสรรหาอื่น ๆ\n\nกฎของการสรรหาพิเศษมีดังนี้:\n\n- รับประกันว่าจะได้ Aurorian 5 ดาวภายในการสรรหา 10 ครั้งแรก\n\n- กลไกเพิ่มความน่าจะเป็นของ Aurorian 6 ดาว: ความน่าจะเป็นเริ่มต้นในการได้รับ Aurorian 6 ดาวจากการสรรหานี้คือ <color=#ffbb00>2%</color> หากคุณไม่สามารถสรรหา Aurorian 6 ดาวหลังจากสรรหา <color=#ffbb00>50</color> ครั้งติดต่อกัน ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวในครั้งถัดไปจะเพิ่มจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color> หากคุณยังไม่สามารถสรรหา Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวในครั้งถัดไปจะเพิ่มจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color> และเช่นกันต่อไป ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> จนถึง <color=#ffbb00>100%</color> หลังจากได้รับ Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะถูกรีเซ็ตเป็น <color=#ffbb00>2%</color>\n\n- กลไกการรับประกัน: หาก Aurorian 6 ดาวที่โดดเด่นในการสรรหาพิเศษนี้ไม่ได้รับภายใน <color=#ffbb00>2</color> ครั้งติดต่อกัน ครั้งถัดไปที่ได้รับ Aurorian 6 ดาวผ่านการสรรหานี้จะ <color=#ffbb00>รับประกัน</color> ว่าเป็น Aurorian 6 ดาวที่โดดเด่น ทุกครั้งที่ได้รับ Aurorian 6 ดาวที่โดดเด่น กลไกการรับประกันจะถูกรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: กลไกเพิ่มความน่าจะเป็นและการรับประกันของการสรรหาพิเศษนี้เป็นอิสระจากกลไกเพิ่มความน่าจะเป็นและการรับประกันของการสรรหาประเภทอื่น ๆ กลไกเพิ่มความน่าจะเป็นและการรับประกันของการสรรหาพิเศษนี้ใช้ได้เฉพาะในช่วงเวลานี้และจะไม่ถือความสำคัญในการสรรหาพิเศษครั้งถัดไป",
  str_draw_card_pool_detail_sub_desc60010_2 = "ในระหว่างการรับสมัคร Lucky Star สุดพิเศษแบบจำกัดเวลา โอกาสในการรับสมัคร Aurorians ต่อไปนี้จะเพิ่มขึ้น:\nเมื่อทำการรับสมัคร Aurorian ระดับ 6 ดาว คุณจะมี <color=#ffbb00>50%</color> โอกาสที่จะได้รับ <color=#ffbb00>โกลดี้</color>.\n\nชาวออโรเรียนที่รับสมัครได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nโกลดี้/ดันตัง/ซาร์ย่า/แอนโทนี่/ลอเรลัย/ซีน่า/โจชัว/ชวาร์ตซ์: อัลไลตี้คลามอร์/ยิงเกิล/เลโอ/ฮาติ/ติน่า/เลน/เจอาย่า/มูเย่บาย/จงซู/วิค/แอกเซเลีย/ลิลิกา/มินอส/โพลลักซ์/เจโน่/เฟีย/คาร์ลีน: สมอลเดอริ่งโซล/นีน่า/บาร์ตัน: เดฟท์เบลดส์/ไจล์ส/เลโอร์/แอเชอร์/เยา/อาเมมอริ/รินเน/ฟลอรีน/รูบี้/เชอวาน/โนวิโอ/เฮดี้/เบเธล/ลุค/พาโลม่า/กรัม/เรวี่/สโมกกี้/เฟลอร์/เบริล/ฮิอิโระ/ซินซา/อีฟ/ยูเรียล/คาร์ลีน/ชาโรนา/ซาเรียล/ราฟาเอล/คอนนอลลี่/ชารอน/อีซีซี/วิกตอเรีย/โจน่า/นิกินิส/กาเบรียล/มิการ์ด/ไมเคิล/กรอนรู/ อิริดอน/ราธ\nออโรเรียน 5 ดาว: 9.5%\nโจเซลีน/บลังค์: ปูราคอร์ดิส/คริสเตน/เคีย/เบเร็ตตา/คาสตา/ซีเอล/ซานาเอ/รอย/คายาโนะ/เอริก้า/โรบิน/คอร์ดี้/นาโรเซล/เจเนวีฟ/ทาคิ/โคแร็กซ์/บาร์ตัน/เคลเคน/ฟิลิชี/โนอาห์/ไฮแดรด/เบนนี่กับคุโระ/เรจินา/เฟาสต์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/อาเรีย/แพกต์/ซิคาเร/ลูอิส/โอดี/คุสคูตา/เดย์นา/ชวาตส์/เนเมซิส/เบเวอร์ลี/คีตติง/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nฮาชิ & กิน/ทวีตตี้/พาโซโล่/เจน/คุมะกับเพนจี้/มิสบลังค์/มิเชนนี่/โคลอี้/คอนสแตนติน/แพตตี้และแพตซี่/โจนี่ บูม/อลิซ/บร็อค/เนลส์/จันทรา/ซิลวา/เลสเตอร์/โจล่า/เวนดี้/ยูรีอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟคา\nออโรเรียน 3 ดาว: 55.5%\nเซลิวซิด/โซย่า/คนแคระขาว/คอร์กอน/ซอค & เบคก์/ไทนี่วัน/เปปี้/คลั่งไคล้ริก/โจมู/โคลเวอร์/โอฟิน่า/โดฟ/ลีอาห์/นางฟ้า/ยูนิเมท/เอโฮ/เอมี่",
