  str_draw_card_pool_name_30001 = "อัญเชิญหมุนเวียน",
  str_draw_card_pool_title_30001_1 = "อัญเชิญหมุนเวียน",
  str_draw_card_pool_title_30001_2 = "เพิ่มอัตราอัญเชิญมิการ์ดกับอิริดอน!",
  str_draw_card_pool_detail_title_30001 = "ข้อมูลอัญเชิญหมุนเวียน",
  str_draw_card_pool_detail_sub_desc30001_1 = "การอัญเชิญหมุนเวียนนี้จะเปิดเป็นช่วง และสามารถใช้สตาร์แฟลร์เพื่ออัญเชิญ หลังจากที่การอัญเชิญหมุนเวียนอัปเดต จะการันตีออโรเรียน 5 ดาวภายในการอัญเชิญ 10 ครั้งแรก\n\nโอกาสเริ่มต้นที่จะได้รับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ <color=#ffbb00>2%</color> หากคุณอัญเชิญไม่ได้ออโรเรียน 6 ดาวหลังจากอัญเชิญ <color=#ffbb00>50</color> ครั้งติดต่อกัน โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color> หากคุณยังคงไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color>เป็นต้น เมื่อคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> ไปเรื่อย ๆ จนกว่าจะถึง <color=#ffbb00>100%</color> หลังจากได้รับออโรเรียน 6 ดาวแล้ว โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น <color=#ffbb00>2%</color>\n\nการอัญเชิญหมุนเวียนทั้งหมดเป็นไปตามกติกาข้างต้น หมายความว่าในการอัญเชิญหมุนเวียนทั้งหมด หากคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับจะสะสมไว้ในการพยายามอัญเชิญครั้งต่อไป โอกาสที่สะสมนี้จะไม่หายไปเมื่อสิ้นสุดการอัญเชิญหมุนเวียน และจะส่งต่อไปยังการอัญเชิญหมุนเวียนครั้งต่อไป หากมีการอัญเชิญหมุนเวียนหลายรายการพร้อมกัน โอกาสนี้จะทบสะสมและมีผลกับแต่ละรายการอย่างสอดคล้อง เมื่อคุณได้รับออโรเรียน 6 ดาวจากการอัญเชิญหมุนเวียนใด ๆ โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น <color=#ffbb00>2%</color>\n\nการอัญเชิญหมุนเวียนมีระบบการันตี ถ้าออโรเรียน 6 ดาวที่ได้รับ <color=#ffbb00>2</color> ครั้งติดกันไม่ใช่ออโรเรียน 6 ดาวที่เพิ่มโอกาสในการอัญเชิญนี้ ออโรเรียน 6 ดาวตัวต่อไปที่ได้รับจากการอัญเชิญนี้จะเป็นออโรเรียน 6 ดาวที่เพิ่มโอกาส<color=#ffbb00>อย่างแน่นอน</color> ทุกครั้งที่ได้รับออโรเรียน 6 ดาวที่เพิ่มโอกาส ระบบการันตีจะรีเซ็ตและคำนวณใหม่ โอกาสที่สะสมนี้จะไม่หายไปเมื่อสิ้นสุดการอัญเชิญหมุนเวียน และจะทบไปยังการอัญเชิญหมุนเวียนครั้งต่อไป หากมีการอัญเชิญหมุนเวียนหลายรายการพร้อมกัน จะใช้ระบบการันตีนี้ร่วมกัน ดังนั้นการพยายามอัญเชิญหมุนเวียนในช่วงเดียวกันจะทำให้ระบบการันตีนำไปคำนวณและรีเซ็ตด้วย ออโรเรียน 6 ดาวที่ได้รับขณะที่ระบบการันตีทำงานจะเป็นไปตามจำนวนครั้งการอัญเชิญหมุนเวียน\n\nโปรดทราบว่าโอกาสที่เพิ่มขึ้นและระบบการันตีของการอัญเชิญหมุนเวียนจะไม่เกี่ยวข้องกับโอกาสที่เพิ่มขึ้นและระบบการันตีของการอัญเชิญประเภทอื่น การเพิ่มโอกาสและระบบการันตีใช้ได้ภายในกาชาอัญเชิญที่เกี่ยวข้องเท่านั้น",
