  str_draw_card_pool_title_30019_2 = "เพิ่มโอกาสได้รับกาบริเอล ไฮแดรด และอีสต์วานในช่วงอีเวนต์!",
  str_draw_card_pool_detail_sub_desc30019_1 = "การอัญเชิญหมุนเวียนจำกัดเวลานี้จะเปิดเป็นช่วง และคุณสามารถใช้สตาร์แฟลร์พิเศษเพื่ออัญเชิญ หลังจากที่การอัญเชิญหมุนเวียนจำกัดเวลาอัปเดต จะการันตีออโรเรียน 5 ดาวภายในการอัญเชิญ 10 ครั้งแรก\n\nโอกาสเริ่มต้นที่จะได้รับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ 2% หากคุณอัญเชิญไม่ได้ออโรเรียน 6 ดาวหลังจากอัญเชิญ 50 ครั้งติดต่อกัน โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก 2% เป็น 4.5% หากคุณยังคงไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก 4.5% เป็น 7% เป็นต้น เมื่ือคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น 2.5% ไปเรื่อย ๆ จนกว่าจะถึง 100% หลังจากได้รับออโรเรียน 6 ดาวแล้ว โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น 2%\n\nการอัญเชิญหมุนเวียนทั้งหมดเป็นไปตามกติกาข้างต้น หมายความว่าในการอัญเชิญหมุนเวียนทั้งหมด หากคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสที่คุณได้รับจะถูกสะสมไว้ โอกาสที่สะสมนี้จะไม่หายไปเมื่อสิ้นสุดการอัญเชิญหมุนเวียน และจะส่งต่อไปยังการอัญเชิญหมุนเวียนครั้งต่อไป หากมีการอัญเชิญหมุนเวียนหลายรายการพร้อมกัน โอกาสนี้จะทบสะสมและมีผลกับแต่ละรายการอย่างสอดคล้อง\n\nเมื่อคุณได้รับออโรเรียน 6 ดาวจากการอัญเชิญเวลาจำกัดใด ๆ โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น 2% โปรดทราบว่าการอัญเชิญจำกัดเวลาและการอัญเชิญตัวหลักเป็นคนละส่วนกัน และการเพิ่มโอกาสใช้ได้ภายในกาชาอัญเชิญที่เกี่ยวข้องเท่านั้น",
  str_draw_card_pool_detail_sub_desc30019_2 = "ในช่วงอัญเชิญหมุนเวียน โอกาสได้รับออโรเรียนต่อไปนี้จะเพิ่มขึ้น\nเมื่ออัญเชิญออโรเรียน 6 ดาว มีโอกาส 50% ที่จะได้รับกาบริเอล\nเมื่ออัญเชิญออโรเรียน 5 ดาว มีโอกาส 25% ที่จะได้รับไฮแดรด\nเมื่ออัญเชิญออโรเรียน 5 ดาว มีโอกาส 25% ที่จะได้รับอีสต์วาน\n\nออโรเรียนที่สามารถอัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nเบเธล/ลุค/พาโลม่า/แกรม/เรวี่/สโมกกี้/เฟลอร์/เบริล/ฮิอิโระ/ซินซา/อีฟ/อูริเอล/คาร์ลีน/ชาโรนา/ซาริเอล/ราฟาเอล/คอนนอลลี/คารอน/เอซี่/วิกตอเรีย/โจนา/นิคินิส/กาบริเอล/มิการ์ด/มิคาเอล/กรอนรู/อิริดอน/วราธ\nออโรเรียน 5 ดาว: 9.5%\nนาโรเซล/เจเนวีฟ/ทาคิ/โคแร็กซ์/บาร์ตัน/เคลเคน/ฟิลิชี/โนอาห์/ไฮแดรด/เบนนี่กับคุโระ/เรจินา/เฟาสต์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/อาเรีย/แพกต์/ซิคาเร/ลูอิส/โอดี/คุสคูตา/เดย์นา/ชวาตส์/เนเมซิส/เบเวอร์ลี/คีตติง/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nฮาชิ & กิน/ทวีตตี้/พาโซโล่/เจน/คุมะกับเพนจี้/มิสบลังค์/มิเชนนี/โคลอี้/คอนสแตนติน/แพตตี้กับแพตซี่/โจแอนนี บูม/อลิซ/บร็อค/เนลส์/แชนดรา/ซิลวา/เลสเตอร์/โจลา/เวนดี้/ยูริอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟกา\nออโรเรียน 3 ดาว: 55.5%\nเซลูซิด/โซยา/ไวท์ดวาร์ฟ/คอร์กอน/ซอร์คกับเบคค์/เจ้าจิ๋ว/เปปี/ริค เลื่อยไฟฟ้า/โจมู/โคลเวอร์/โอฟินา/โดฟ/ลีอาห์/แองเจิล/ยูนิเมต/เอโฮะ/เอมี่",
