  str_draw_card_pool_detail_sub_desc50026_2 = "Aurorians ที่รับสมัครทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nคาร์ลีน: วิญญาณที่คุกรุ่น/ไจล์ส/รินน์/โนวิโอ/แกรม/สโมคกี้/ซินซา/อูเรียล/ชารอน/อีซี/วิกตอเรีย/โจน่า\nออโรเรียน 5 ดาว: 9.5%\nCordy/Genevieve/Taki/Benny และ Curo/Regina/Faust/Maggie/Istvan/Barbara/Leona\nออโรเรียน 4 ดาว: 33.0%\nPatty & Patsy/Joanie Boom/Alice/Brock/Nails/Chandra\nออโรเรียน 3 ดาว: 55.5%\nSork & Bekk/Tiny One/Pepi/คลั่งริก",
  str_draw_card_pool_name_50003 = "การอัญเชิญแบบเลือกเป้าหมาย: ธาตุไม้",
  str_draw_card_pool_des_50003 = "การันตีออโรเรียนธาตุไม้ 5 ดาวภายในการอัญเชิญ 10 ครั้งแรก",
