  str_draw_card_pool_detail_title_50009 = "ข้อมูลการอัญเชิญแบบเลือกเป้าหมาย: คอนเวอร์เตอร์",
  str_draw_card_pool_detail_sub_desc50009_1 = "การอัญเชิญแบบเลือกเป้าหมายตามคลาสจะเปิดในช่วงเวลาจำกัด ซึ่งจะมีตู้กาชาทั้งหมด 4 คลาสในช่วงเวลา 4 สัปดาห์ โดยจะเปิดสัปดาห์ละ 1 คลาส ตามลำดับต่อไปนี้:\nคอนเวอร์เตอร์ (สัปดาห์ที่ 1): 28 เม.ย. - 5 พ.ค.\nสไนเปอร์ (สัปดาห์ที่ 2): 5 พ.ค. - 12 พ.ค.\nสนับสนุน (สัปดาห์ที่ 3): 12 พ.ค. - 19 พ.ค.\nเดโทเนเตอร์ (สัปดาห์ที่ 4): 19 พ.ค. - 26 พ.ค.\n\nการอัญเชิญนี้เป็นการเจาะจงเฉพาะคอนเวอร์เตอร์ ซึ่งหมายความว่าคุณจะได้รับแต่ออโรเรียนคอนเวอร์เตอร์จากตู้กาชานี้ สามารถใช้สตาร์แฟลร์อัญเชิญได้ และการันตีว่าจะได้รับออโรเรียนคอนเวอร์เตอร์ 5 ดาว 1 ราย ในการอัญเชิญ 10 ครั้งแรก\n\nโอกาสได้รับตัวละครเรตติ้งระดับต่าง ๆ ในการอัญเชิญจะเท่ากับการอัญเชิญปกติ สำหรับรายละเอียด โปรดดูข้อมูลโอกาสการได้รับออโรเรียน\n\nโอกาสเริ่มต้นที่จะได้รับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ 2% หากคุณไม่ได้รับออโรเรียน 6 ดาวหลังจากอัญเชิญ 50 ครั้งติดต่อกัน โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก 2% เป็น 4.5% หากคุณไม่ได้รับออโรเรียน 6 ดาวจากการอัญเชิญครั้งนี้ โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก 4.5% เป็น 7% เป็นต้น เมื่อใดก็ตามที่คุณไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น 2.5% ไปเรื่อย ๆ จนกว่าจะถึง 100% หลังจากได้รับออโรเรียน 6 ดาวแล้ว โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น 2%\n\nหมายเหตุ: ในการอัญเชิญแบบเลือกเป้าหมายตามคลาสนี้ (หมายถึงทั้ง 4 กลุ่ม ตั้งแต่ 28 เม.ย. - 26 พ.ค.) โอกาสได้รับออโรเรียน 6 ดาวที่เพิ่มขึ้นสามารถใช้ร่วมกันได้ ตัวอย่างเช่น ถ้าคุณไม่ได้รับออโรเรียน 6 ดาว ตู้กาชาจะสะสมจำนวนครั้งที่อัญเชิญเอาไว้ แล้วส่งต่อไปตู้ถัดไป ซึ่งก็เท่ากับว่าการอัญเชิญทั้ง 4 คลาส จะนับโอกาสตามกติกาที่กล่าวไว้ข้างต้นโดยไม่แยกกัน โอกาสที่เพิ่มขึ้นสำหรับการอัญเชิญแบบเลือกเป้าหมายตามคลาสจะไม่เกี่ยวข้องกับการอัญเชิญอื่นในช่วงเวลาเดียวกัน และจะไม่ทบสะสมกับการอัญเชิญอื่นในอนาคต",
  str_draw_card_pool_detail_sub_desc50009_2 = "ออโรเรียนที่อัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nอาเมะโมริ/เชอวาน/เอซี่/อูริเอล/คาร์ลีน/รูบี้/ซาริเอล/รินเนะ/สโมกกี้/กรอนรู/เฮดี้/กาบริเอล/นิคินิส/อิริดอน\nออโรเรียน 5 ดาว: 9.5%\nเบเวอร์ลี/แม็กกี้/แพกต์/เนเมซิส/เจเนวีฟ/เฟาสต์/บาร์ตัน/ซิคาเร/เคลเคน\nออโรเรียน 4 ดาว: 33.0%\nโจลา/แอนเซีย/พาโซโล่/มิเชนนี/โจแอนนี บูม/ทวีตตี้/มิสบลังค์/เวนดี้\nออโรเรียน 3 ดาว: 55.5%\nยูนิเมต/เอโฮะ/โดฟ/เปปี/เจ้าจิ๋ว/โอฟินา",
