  str_draw_card_pool_detail_sub_desc60003_2 = "ในช่วงอีเวนต์อัญเชิญเอ็กซ์คลูซีฟราชินีแห่งแดนเหนือ โอกาสได้รับออโรเรียนต่อไปนี้จะเพิ่มขึ้น\nเมื่ออัญเชิญออโรเรียน 6 ดาว มีโอกาส <color=#ffbb00>50%</color> ที่จะได้รับ<color=#ffbb00>เบธเลเฮม</color>\n\nออโรเรียนที่สามารถอัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nเบธเลเฮม/นีน่า/บาร์ตัน: ดาบสำแดงเดช/ไจลส์/เลนอร์/แอเชอร์/เหยา/อาเมะโมริ/รินเนะ/รูบี้/ฟลอรีน/เชอวาน/โนวิโอ/เฮดี้/เบเธล/ลุค/พาโลม่า/แกรม/เรวี่/สโมกกี้/เฟลอร์/เบริล/ฮิอิโระ/ซินซา/อีฟ/อูริเอล/คาร์ลีน/ชาโรนา/ซาริเอล/ราฟาเอล/คอนนอลลี/คารอน/เอซี่/วิกตอเรีย/โจนา/นิคินิส/กาบริเอล/มิการ์ด/มิคาเอล/กรอนรู/อิริดอน/วราธ\nออโรเรียน 5 ดาว: 9.5%\nซานาเอะ/รอย/คายาโนะ/เอริก้า/โรบิน/คอร์ดี้/นาโรเซล/เจเนวีฟ/ทาคิ/โคแร็กซ์/บาร์ตัน/เคลเคน/ฟิลิชี/โนอาห์/ไฮแดรด/เบนนี่กับคุโระ/เรจินา/เฟาสต์/แม็กกี้/อีสต์วาน/บาร์บาร่า/ลีโอนา/อาเรีย/แพกต์/ซิคาเร/ลูอิส/โอดี/คุสคูตา/เดย์นา/ชวาตส์/เนเมซิส/เบเวอร์ลี/คีตติง/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nฮาชิ & กิน/ทวีตตี้/พาโซโล่/เจน/คุมะกับเพนจี้/มิสบลังค์/มิเชนนี/โคลอี้/คอนสแตนติน/แพตตี้กับแพตซี่/โจแอนนี บูม/อลิซ/บร็อค/เนลส์/แชนดรา/ซิลวา/เลสเตอร์/โจลา/เวนดี้/ยูริอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟกา\nออโรเรียน 3 ดาว: 55.5%\nเซลูซิด/โซยา/ไวท์ดวาร์ฟ/คอร์กอน/ซอร์คกับเบคค์/เจ้าจิ๋ว/เปปี/ริค เลื่อยไฟฟ้า/โจมู/โคลเวอร์/โอฟินา/โดฟ/ลีอาห์/แองเจิล/ยูนิเมต/เอโฮะ/เอมี่",
  str_draw_card_pool_detail_sub_desc60004_2 = "ในการรับสมัครพิเศษของ Queen of the North โอกาสในการรับสมัคร Aurorians ต่อไปนี้จะเพิ่มขึ้น:\nเมื่อทำการรับสมัคร Aurorian ระดับ 6 ดาว จะมี <color=#ffbb00>50%</color> โอกาสที่มันจะเป็น <color=#ffbb00>เบธเลเฮม</color>.\n\nชาวออโรเรียนที่รับสมัครได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nBethlehem/Axelia/Lilica/Minos/Pollux/Jeno/Fia/Carleen: Smoldering Soul/Nina/Barton: Deft Blades/Giles/Lenore/Azure/Yao/Amemori/Rinne/Ruby/Florine/Siobhan/Novio/Hedy/Bethel/ ลุค/พาโลมา/กรัม/เรวี่/สโมคกี้/เฟลอร์/เบริล/ฮิอิโระ/ซินซา/อีฟ/ยูเรียล/คาร์ลีน/ชาโรนา/ซาเรียล/ราฟาเอล/คอนนอลลี่/ชารอน/อีซีซี/วิกตอเรีย/โจน่า/นิกินิส/กาเบรียล/มิการ์ด/ไมเคิล/กรอนรู/ อิริดอน/ราธ\nออโรเรียน 5 ดาว: 9.5%\nBeretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Robyn/Cordy/Naroxel/Genevieve/Taki/Corax/Barton/Kleken/Philyshy/Noah/Hydrad/Benny and Curo/Regina/Faust/Maggie/Istvan/Barbara/ Leona/Areia/Pact/Sikare/Louise/Odi/Cuscuta/Dayna/Schwartz/Nemesis/Beverly/Keating/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nHachi & Gin/Tweety/Pasolo/เจน/คุมะ&เพ็งกี้/Ms. บล็อง/มิเชนนี่/โคลอี้/คอนสแตนติน/แพตตี้และแพตซี่/โจนี่ บูม/อลิซ/บร็อค/เนลส์/จันทรา/ซิลวา/เลสเตอร์/โจล่า/เวนดี้/ยูรีอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟคา\nออโรเรียน 3 ดาว: 55.5%\nเซลิวซิด/โซย่า/คนแคระขาว/คอร์กอน/ซอค & เบคก์/ไทนี่วัน/เปปี้/คลั่งไคล้ริก/โจมู/โคลเวอร์/โอฟิน่า/โดฟ/ลีอาห์/นางฟ้า/ยูนิเมท/เอโฮ/เอมี่",
  str_draw_card_pool_name_60005 = "Lucky Star รับสมัครงานพิเศษ",
  str_draw_card_pool_title_60005_1 = "ดาวนำโชค",
  str_draw_card_pool_title_60005_2 = "เพิ่มโอกาสในการรับสมัครโกลดี้ในช่วงเวลากิจกรรม!",
  str_draw_card_pool_detail_title_60005 = "ข้อมูลการรับสมัครงานพิเศษของ Lucky Star",
  str_draw_card_pool_detail_sub_desc60005_1 = "การรับสมัครแบบเอกสิทธิ์เฉพาะบุคคลนี้จะเปิดให้ใช้งานในระยะเวลาจำกัดในช่วงเวลาที่กำหนด สามารถใช้ Special Star Flares เพื่อเกณฑ์ทหารจากแหล่งรวมนี้ ซึ่งรวมถึง Aurorian แบบพิเศษและมีเวลาจำกัด Aurorian สุดพิเศษสำหรับแบนเนอร์รับสมัครนี้คือ Aurorian Goldie 6 ดาว เมื่อทำการเกณฑ์ Aurorian ระดับ 6 ดาว คุณจะมีโอกาส 50% ในการเกณฑ์ <color=#ffbb00>โกลดี้</color>. ตัวละครนี้จะไม่ปรากฏในการรับสมัครอื่น ๆ\n\nกฎการรับสมัครพิเศษมีดังนี้:\n\n- รับประกัน Aurorian ระดับ 5 ดาวภายในการรับสมัคร 10 ครั้งแรกของคุณ\n\n- Aurorian นี้สามารถรับได้จาก <color=#ffbb00>การรับสมัครพิเศษ</color> และไม่สามารถหาได้จากการรับสมัครอื่นๆ Aurorian พิเศษ <color=#ffbb00>โกลดี้</color> จะไม่สามารถใช้ได้ด้วยวิธีอื่นใดหลังจากการรับสมัครนี้สิ้นสุดลง จนกว่าอย่างน้อย <color=#ffbb00>30 มิถุนายน 2566</color>. โปรดดูประกาศอย่างเป็นทางการสำหรับรายละเอียดความพร้อมใช้งานในอนาคตหลังจากการรับสมัครนี้สิ้นสุดลง\n\n- กลไกเพิ่มความน่าจะเป็นออโรเรียน 6 ดาว: ความน่าจะเป็นเริ่มต้นในการได้รับออโรเรียน 6 ดาวจากการรับสมัครนี้คือ <color=#ffbb00>2%</color>. หากคุณล้มเหลวในการรับสมัคร Aurorian 6 ดาวหลังจากนั้น <color=#ffbb00>50</color> การรับสมัครติดต่อกัน ความน่าจะเป็นที่จะได้รับ Aurorian 6 ดาวในการพยายามรับสมัครครั้งต่อไปของคุณจะเพิ่มขึ้นจาก <color=#ffbb00>2%</color> ถึง <color=#ffbb00>4.5%</color>. หากคุณยังไม่สามารถเกณฑ์ Aurorian ระดับ 6 ดาวได้ ความน่าจะเป็นที่จะได้รับ Aurorian ระดับ 6 ดาวในความพยายามครั้งถัดไปของคุณจะเพิ่มขึ้นจาก <color=#ffbb00>4.5%</color> ถึง <color=#ffbb00>7%</color>และอื่น ๆ เมื่อใดก็ตามที่คุณล้มเหลวในการเกณฑ์ Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> จนกว่าจะถึง <color=#ffbb00>100%</color>. หลังจากได้รับ Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะถูกรีเซ็ตเป็น <color=#ffbb00>2%</color>.\n\n- กลไกการรับประกัน: หากไม่ได้ Aurorian 6 ดาวที่โดดเด่นในการรับสมัครพิเศษนี้ภายใน <color=#ffbb00>2</color> ความพยายามติดต่อกัน จากนั้น Aurorian 6 ดาวคนต่อไปที่ได้รับจากการรับสมัครนี้คือ <color=#ffbb00>รับประกัน</color> เพื่อเป็น Aurorian ระดับ 6 ดาวที่โดดเด่น ทุกครั้งที่ได้รับ Aurorian ระดับ 6 ดาวที่โดดเด่น กลไกการรับประกันจะถูกรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: ความน่าจะเป็นที่เพิ่มขึ้นของการรับสมัครและกลไกการรับประกันนี้ไม่ขึ้นกับกลไกความน่าจะเป็นและการรับประกันที่เพิ่มขึ้นของการสรรหาประเภทอื่นๆ ความน่าจะเป็นที่เพิ่มขึ้นของการรับสมัครแบบพิเศษนี้และกลไกการรับประกันจะใช้ได้ในช่วงเวลานี้เท่านั้น และจะไม่ถูกนำไปใช้ในการรับสมัครแบบพิเศษครั้งถัดไป",
  str_draw_card_pool_detail_sub_desc60005_2 = "ในระหว่างการรับสมัคร Lucky Star สุดพิเศษแบบจำกัดเวลา โอกาสในการรับสมัคร Aurorians ต่อไปนี้จะเพิ่มขึ้น:\nเมื่อทำการรับสมัคร Aurorian ระดับ 6 ดาว คุณจะมี <color=#ffbb00>50%</color> โอกาสที่จะได้รับ <color=#ffbb00>โกลดี้</color>.\n\nชาวออโรเรียนที่รับสมัครได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nGoldie/Axelia/Lilica/Minos/Pollux/Jeno/Fia/Carleen: Smoldering Soul/Nina/Barton: Deft Blades/Giles/Lenore/Azure/Yao/Amemori/Rinne/Florine/Ruby/Siobhan/Novio/Hedy/Bethel/ ลุค/พาโลมา/กรัม/เรวี่/สโมคกี้/เฟลอร์/เบริล/ฮิอิโระ/ซินซา/อีฟ/ยูเรียล/คาร์ลีน/ชาโรนา/ซาเรียล/ราฟาเอล/คอนนอลลี่/ชารอน/อีซีซี/วิกตอเรีย/โจน่า/นิกินิส/กาเบรียล/มิการ์ด/ไมเคิล/กรอนรู/ อิริดอน/ราธ\nออโรเรียน 5 ดาว: 9.5%\nBeretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Robyn/Cordy/Naroxel/Genevieve/Taki/Corax/Barton/Kleken/Philyshy/Noah/Hydrad/Benny and Curo/Regina/Faust/Maggie/Istvan/Barbara/ Leona/Areia/Pact/Sikare/Louise/Odi/Cuscuta/Dayna/Schwartz/Nemesis/Beverly/Keating/วิเวียน/มีอา\nออโรเรียน 4 ดาว: 33.0%\nHachi & Gin/Tweety/Pasolo/เจน/คุมะ&เพ็งกี้/Ms. บล็อง/มิเชนนี่/โคลอี้/คอนสแตนติน/แพตตี้และแพตซี่/โจนี่ บูม/อลิซ/บร็อค/เนลส์/จันทรา/ซิลวา/เลสเตอร์/โจล่า/เวนดี้/ยูรีอาห์/เทสซา/แอนเซีย/นาดีน/แรบบี้/ลิลเลียม/คาฟคา\nออโรเรียน 3 ดาว: 55.5%\nเซลิวซิด/โซย่า/คนแคระขาว/คอร์กอน/ซอค & เบคก์/ไทนี่วัน/เปปี้/คลั่งไคล้ริก/โจมู/โคลเวอร์/โอฟิน่า/โดฟ/ลีอาห์/นางฟ้า/ยูนิเมท/เอโฮ/เอมี่",
  str_draw_card_pool_detail_sub_desc60006_1 = "การรับสมัครแบบเอกสิทธิ์เฉพาะบุคคลนี้เปิดในระยะเวลาจำกัดในช่วงเวลาที่กำหนด และสามารถใช้ Special Star Flares เพื่อเกณฑ์ทหารจากกลุ่มนี้ได้ ซึ่งรวมถึง Aurorian แบบเอกสิทธิ์เฉพาะบุคคลแบบจำกัดเวลา ออโรเรียนสำหรับป้ายรับสมัครนี้คือออโรเรียน 6 ดาว <color=#ffbb00>เรนฮาร์ด</color>. เมื่อทำการเกณฑ์ Aurorian ระดับ 6 ดาว คุณจะมีโอกาส 50% ในการเกณฑ์ <color=#ffbb00>เรนฮาร์ด</color>. ตัวละครนี้จะไม่ปรากฏในการรับสมัครอื่น ๆ\n\nรายละเอียดกฎการรับสมัครพิเศษมีดังนี้:\n\n- รับประกัน Aurorian ระดับ 5 ดาวภายในการรับสมัคร 10 ครั้งแรกของคุณ\n\n- Aurorian นี้สามารถรับได้จาก <color=#ffbb00>การรับสมัครพิเศษ</color> และจะไม่ถูกเพิ่มเข้าไปในรายชื่อตัวละครที่ได้รับในการรับสมัครประเภทอื่นๆ Aurorian พิเศษ <color=#ffbb00>เรนฮาร์ด</color> จะไม่สามารถใช้ได้ในการสรรหาอื่น ๆ ยกเว้นการสรรหาพิเศษ\n\n- กลไกเพิ่มความน่าจะเป็นออโรเรียน 6 ดาว: ความน่าจะเป็นเริ่มต้นในการได้รับออโรเรียน 6 ดาวจากการรับสมัครนี้คือ <color=#ffbb00>2%</color>. หากคุณล้มเหลวในการเกณฑ์ Aurorian 6 ดาวหลังจากนั้น <color=#ffbb00>50</color> การรับสมัครติดต่อกัน ความน่าจะเป็นที่จะได้รับ Aurorian 6 ดาวในการพยายามรับสมัครครั้งต่อไปของคุณจะเพิ่มขึ้นจาก <color=#ffbb00>2%</color> ถึง <color=#ffbb00>4.5%</color>. หากคุณยังไม่สามารถเกณฑ์ Aurorian ระดับ 6 ดาวได้ ความน่าจะเป็นที่จะได้รับ Aurorian ระดับ 6 ดาวในความพยายามครั้งถัดไปของคุณจะเพิ่มขึ้นจาก <color=#ffbb00>4.5%</color> ถึง <color=#ffbb00>7%</color>และอื่น ๆ เมื่อใดก็ตามที่คุณล้มเหลวในการเกณฑ์ Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> จนกว่าจะถึง <color=#ffbb00>100%</color>. หลังจากได้รับ Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะถูกรีเซ็ตเป็น <color=#ffbb00>2%</color>.\n\n- กลไกการรับประกัน: ในการรับสมัครพิเศษ หากไม่ได้รับ Aurorian ระดับ 6 ดาวในการรับสมัครนี้ภายใน <color=#ffbb00>2</color> ความพยายามติดต่อกัน จากนั้น Aurorian 6 ดาวคนต่อไปที่ได้รับจากการรับสมัครนี้คือ <color=#ffbb00>รับประกัน</color> เพื่อเป็น Aurorian ระดับ 6 ดาวที่โดดเด่น ทุกครั้งที่ได้รับ Aurorian ระดับ 6 ดาวที่โดดเด่น กลไกการรับประกันจะถูกรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: ความน่าจะเป็นที่เพิ่มขึ้นของการรับสมัครและกลไกการรับประกันนี้ไม่ขึ้นกับกลไกความน่าจะเป็นและการรับประกันที่เพิ่มขึ้นของการสรรหาบุคลากรประเภทอื่นๆ ความน่าจะเป็นที่เพิ่มขึ้นของการรับสมัครแบบพิเศษนี้และกลไกการรับประกันจะใช้ได้ในช่วงเวลานี้เท่านั้น และจะไม่ถูกนำไปใช้ในการรับสมัครแบบพิเศษครั้งถัดไป",
  str_draw_card_pool_name_50018 = "อัญเชิญแนะนำกองหนุนอัมบราตัน",
