  str_draw_card_pool_detail_title_50018 = "ข้อมูลอัญเชิญแนะนำกองหนุนอัมบราตัน",
  str_draw_card_pool_detail_sub_desc50018_1 = "นี่คือการอัญเชิญจำกัดเวลา และคุณสามารถใช้สตาร์แฟลร์พิเศษเพื่ออัญเชิญ การันตีออโรเรียน 5 ดาวภายในการอัญเชิญ 10 ครั้งแรก\n\nโอกาสได้รับตัวละครเรตติ้งระดับต่าง ๆ ในการอัญเชิญจะเท่ากับการอัญเชิญปกติ สำหรับรายละเอียด โปรดดูข้อมูลโอกาสการได้รับออโรเรียน\n\nโอกาสเริ่มต้นที่จะได้รับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ 2% หากคุณอัญเชิญไม่ได้ออโรเรียน 6 ดาวหลังจากอัญเชิญ 50 ครั้งติดต่อกัน โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก 2% เป็น 4.5% หากคุณยังคงไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวในการอัญเชิญครั้งต่อไปจะเพิ่มขึ้นจาก 4.5% เป็น 7% เป็นต้น เมื่ือคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น 2.5% ไปเรื่อย ๆ จนกว่าจะถึง 100% หลังจากได้รับออโรเรียน 6 ดาวแล้ว โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น 2%\nการอัญเชิญนี้และการอัญเชิญหมุนเวียนเป็นไปตามกติกาเดียวกันข้างต้น หมายความว่าในการอัญเชิญนี้และการอัญเชิญหมุนเวียน หากคุณไม่ได้รับออโรเรียน 6 ดาว โอกาสที่คุณได้รับจะถูกสะสมไว้ โอกาสที่สะสมนี้จะไม่หายไปเมื่อสิ้นสุดการอัญเชิญนี้และการอัญเชิญหมุนเวียน และจะส่งต่อไปยังการอัญเชิญหมุนเวียนหรือการอัญเชิญธรรมดาครั้งต่อไป ในกรณีที่มีการอัญเชิญหลายรายการพร้อมกัน โอกาสนี้จะทบสะสมและมีผลกับแต่ละรายการโดยสอดคล้องกัน\nโปรดทราบว่าโอกาสการอัญเชิญที่เพิ่มขึ้นนี้ไม่เกี่ยวข้องกับการอัญเชิญประเภทอื่น โอกาสที่เพิ่มขึ้นจะมีผลภายในกลุ่มการอัญเชิญที่เกี่ยวข้องเท่านั้น\nเมื่อคุณได้รับออโรเรียน 6 ดาวจากการอัญเชิญเวลาจำกัดใด ๆ โอกาสได้รับออโรเรียน 6 ดาวจะรีเซ็ตเป็น 2%\n\nการอัญเชิญนี้ไม่มีระบบการันตี และไม่มีผลต่อระบบการันตีในการอัญเชิญอื่น ๆ",
  str_draw_card_pool_detail_sub_desc50018_2 = "ออโรเรียนที่สามารถอัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nลุค/สโมกกี้/ซาริเอล/เบเธล/คอนนอลลี\nออโรเรียน 5 ดาว: 9.5%\nอาเรีย/ไฮแดรด/ลีโอนา/โคแร็กซ์/คุสคูตา/ทาคิ/โรบิน/เคลเคน/เดย์นา/อีสต์วาน\nออโรเรียน 4 ดาว: 33.0%\nเจน/ฮาชิ & กิน/เทสซา/แพตตี้กับแพตซี่\nออโรเรียน 3 ดาว: 55.5%\nเซลูซิด",
  str_draw_card_pool_name_70001 = "อัญเชิญเอ็กซ์คลูซีฟคอลแลปดีต่อต้านชั่ว",
  str_draw_card_pool_title_70001_1 = "อัญเชิญเอ็กซ์คลูซีฟคอลแลปดีต่อต้านชั่ว",
  str_draw_card_pool_title_70001_2 = "เพิ่มโอกาสได้รับโทรุและลูโคอาในช่วงอีเวนต์!",
  str_draw_card_pool_detail_title_70001 = "ข้อมูลอัญเชิญเอ็กซ์คลูซีฟคอลแลปดีปะปรายกับชั่ว",
  str_draw_card_pool_detail_sub_desc70001_1 = "การอัญเชิญเอ็กซ์คลูซีฟคอลแลปนี้เปิดในช่วงเวลาจำกัดตามช่วงเวลาที่กำหนด สตาร์แฟลร์พิเศษและจิตวิญญาณอัญเชิญคอลแลป ×10 สามารถใช้เพื่ออัญเชิญจากกลุ่มนี้ ซึ่งรวมถึงออโรเรียนเวลาจำกัดหลายตัว\nออโรเรียนพิเศษในครั้งนี้คือออโรเรียน 6 ดาว <color=#ffbb00>โทรุ</color> และออโรเรียน 5 ดาว <color=#ffbb00>ลูโคอา</color> เมื่ออัญเชิญออโรเรียน 6 ดาว คุณจะมีโอกาส <color=#ffbb00>50%</color> ในการอัญเชิญโทรุ และเมื่ออัญเชิญออโรเรียน 5 ดาว คุณจะมีโอกาส <color=#ffbb00>25%</color> ในการอัญเชิญลูโคอา ตัวละครเหล่านี้จะไม่ปรากฏในการอัญเชิญอื่น ๆ\n\nรายละเอียดกฎการอัญเชิญเอ็กซ์คลูซีฟคอลแลปดังนี้:\n\n- ออโรเรียน 5 ดาวจะได้รับการรับประกันภายในการอัญเชิญ 10 ครั้งแรกของคุณ\n\n- ออโรเรียนเอ็กซ์คลูซีฟคอลแลป <color=#ffbb00>โทรุ</color> และ <color=#ffbb00>ลูโคอา</color> จะมีให้เฉพาะในการอัญเชิญเอ็กซ์คลูซีฟคอลแลป ดีเทียบกับชั่ว และจะไม่ถูกเพิ่มเข้าไปในรายชื่อตัวละครที่สามารถรับได้ในการอัญเชิญประเภทอื่น ๆ\n- กลไกเพิ่มความน่าจะเป็นของออโรเรียน 6 ดาว: ความน่าจะเป็นเริ่มต้นในการรับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ <color=#ffbb00>2%</color> หากคุณไม่สามารถอัญเชิญออโรเรียน 6 ดาวหลังจากการอัญเชิญ <color=#ffbb00>50</color> ครั้งติดต่อกัน ความน่าจะเป็นในการรับออโรเรียน 6 ดาวในครั้งถัดไปของคุณจะเพิ่มจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color> หากคุณยังไม่สามารถอัญเชิญออโรเรียน 6 ดาว ความน่าจะเป็นในการรับออโรเรียน 6 ดาวในครั้งถัดไปของคุณจะเพิ่มจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color> และเช่นกัน ทุกครั้งที่คุณไม่สามารถอัญเชิญออโรเรียน 6 ดาว ความน่าจะเป็นในการรับออโรเรียน 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> จนถึง <color=#ffbb00>100%</color> หลังจากได้รับออโรเรียน 6 ดาว ความน่าจะเป็นในการรับออโรเรียน 6 ดาวจะถูกรีเซ็ตเป็น <color=#ffbb00>2%</color>\n- กลไกการรับประกัน: ในการอัญเชิญเอ็กซ์คลูซีฟคอลแลป หากออโรเรียน 6 ดาวที่โดดเด่นในการอัญเชิญนี้ไม่ได้รับภายใน <color=#ffbb00>2</color> ครั้งที่ติดต่อกัน ออโรเรียน 6 ดาวถัดไปที่ได้รับผ่านการอัญเชิญนี้จะ <color=#ffbb00>แน่นอน</color> เป็นออโรเรียน 6 ดาวที่โดดเด่น ทุกครั้งที่ได้รับออโรเรียน 6 ดาวที่โดดเด่น กลไกการรับประกันจะถูกรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: การเพิ่มความน่าจะเป็นและกลไกการรับประกันของการอัญเชิญเอ็กซ์คลูซีฟคอลแลปนี้เป็นอิสระจากการเพิ่มความน่าจะเป็นและกลไกการรับประกันของการอัญเชิญประเภทอื่น ๆ การเพิ่มความน่าจะเป็นและกลไกการรับประกันของการอัญเชิญเอ็กซ์คลูซีฟคอลแลปนี้ใช้ร่วมกันกับการอัญเชิญ External Order แต่จะไม่ถือความน่าจะเป็นและกลไกการรับประกันไปสู่การอัญเชิญเอ็กซ์คลูซีฟคอลแลปถัดไป",
