  str_draw_card_pool_detail_sub_desc90002_2 = "ข้อมูลโอกาสได้รับ Aurorian\nออโรเรียน 6 ดาว: 2.0%\nออโรเรียน 5 ดาว: 9.5%\nออโรเรียน 4 ดาว: 33.0%\nออโรเรียน 3 ดาว: 55.5%",
  str_draw_card_pool_name_60008 = "Twilight Symphony อัญเชิญเอ็กซ์คลูซีฟ",
  str_draw_card_pool_title_60008_1 = "ซิมโฟนีทไวไลท์",
  str_draw_card_pool_title_60008_2 = "เพิ่มโอกาสได้รับ วราธ: กระตือรือร้นภูมิใจ และโจเซลีนในช่วงอีเวนต์!",
  str_draw_card_pool_detail_title_60008 = "ข้อมูลการรับสมัครงานพิเศษของ Twilight Symphony",
  str_draw_card_pool_detail_sub_desc60008_1 = "การสรรหาพิเศษครั้งนี้จะมีให้บริการเฉพาะระยะเวลาที่กำหนด คุณสามารถใช้ Special Star Flares เพื่อสรรหาจากกลุ่มนี้ ซึ่งรวมถึงออโรเรียน 6 ดาวพิเศษ <color=#ffbb00>Wrath: Proud Fervor</color> และออโรเรียน 5 ดาวที่ไม่เป็นพิเศษ <color=#ffbb00>Joselyne</color> เมื่อสรรหาออโรเรียน 6 ดาว คุณจะมีโอกาส 50% ในการสรรหา Wrath: Proud Fervor และเมื่อสรรหาออโรเรียน 5 ดาว คุณจะมีโอกาส 25% ในการสรรหา Joselyne ออโรเรียน 2 ตัวนี้จะไม่ปรากฏในการสรรหาครั้งอื่น ๆ\n\nกฎการสรรหาพิเศษมีดังนี้:\n\n- ออโรเรียน 5 ดาวจะได้รับการรับประกันภายในการสรรหา 10 ครั้งแรกของคุณ\n\n- ออโรเรียนนี้สามารถสรรหาได้เฉพาะจาก <color=#ffbb00>การสรรหาพิเศษ</color> และจะไม่สามารถรับได้จากการสรรหาครั้งอื่น ๆ ออโรเรียนพิเศษ <color=#ffbb00>Wrath: Proud Fervor</color> จะไม่สามารถใช้วิธีอื่นใดหลังจากการสรรหาครั้งนี้สิ้นสุด จนกว่าจะถึงวันที่ <color=#ffbb00>29 กุมภาพันธ์ 2567</color> โปรดดูประกาศทางการสำหรับรายละเอียดเกี่ยวกับความพร้อมในอนาคตหลังจากการสรรหาครั้งนี้สิ้นสุด\n\n- Joselyne เป็นออโรเรียน 5 ดาวที่ไม่เป็นพิเศษ หลังจาก Twilight Symphony Exclusive Recruitment, Joselyne จะถูกเพิ่มเข้าไปใน Mainstay Recruitment และการสรรหาเวลาจำกัดทั้งหมดในภายหลังผ่านการอัปเดต ออโรเรียนที่สามารถรับได้จาก Mainstay Recruitment และการสรรหาเวลาจำกัดที่ตามมาทั้งหมดจะมีโอกาสปรากฏเท่ากับออโรเรียนที่ไม่ใช่เหตุการณ์เดียวกันของเรตติ้งเดียวกัน\n\n- กลไกเพิ่มความน่าจะเป็นของออโรเรียน 6 ดาว: ความน่าจะเป็นเริ่มต้นในการรับออโรเรียน 6 ดาวจากการสรรหาครั้งนี้คือ <color=#ffbb00>2%</color> หากคุณไม่สามารถสรรหาออโรเรียน 6 ดาวหลังจาก <color=#ffbb00>50</color> การสรรหาติดต่อกัน ความน่าจะเป็นในการรับออโรเรียน 6 ดาวในครั้งถัดไปของคุณจะเพิ่มจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color> หากคุณยังไม่สามารถสรรหาออโรเรียน 6 ดาว ความน่าจะเป็นในการรับออโรเรียน 6 ดาวในครั้งถัดไปของคุณจะเพิ่มจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color> และอื่น ๆ ความน่าจะเป็นในการรับออโรเรียน 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> จนถึง <color=#ffbb00>100%</color> หลังจากได้รับออโรเรียน 6 ดาว ความน่าจะเป็นในการรับออโรเรียน 6 ดาวจะถูกรีเซ็ตเป็น <color=#ffbb00>2%</color>\n\n- กลไกการรับประกัน: หากออโรเรียน 6 ดาวที่โดดเด่นในการสรรหาพิเศษครั้งนี้ไม่ได้รับภายใน <color=#ffbb00>2</color> ครั้งที่ติดต่อกัน ออโรเรียน 6 ดาวถัดไปที่ได้รับผ่านการสรรหานี้จะ <color=#ffbb00>รับประกัน</color> ว่าเป็นออโรเรียน 6 ดาวที่โดดเด่น ทุกครั้งที่ได้รับออโรเรียน 6 ดาวที่โดดเด่น กลไกการรับประกันจะถูกรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: กลไกเพิ่มความน่าจะเป็นและการรับประกันของการสรรหาพิเศษครั้งนี้เป็นอิสระจากกลไกเพิ่มความน่าจะเป็นและการรับประกันของประเภทการสรรหาอื่น ๆ กลไกเพิ่มความน่าจะเป็นและการรับประกันของ Twilight Symphony ใช้ได้เฉพาะระหว่างช่วงเวลานี้และจะไม่ถือคืนไปยังการสรรหาพิเศษครั้งถัดไป",
