  str_draw_card_pool_detail_sub_desc50047_1 = "นี่เป็นการสรรหาในระยะเวลาจำกัด และคุณสามารถใช้ Star Flares เพื่อสรรหาจากที่นี่ รับประกันว่าจะได้ Aurorian 5 ดาวภายใน 10 ครั้งแรกของการสรรหา\n\nความน่าจะเป็นในการได้รับตัวละครที่มีคะแนนต่างๆในการสรรหานี้จะเท่ากับการสรรหาปกติ สำหรับรายละเอียด โปรดอ้างอิงถึงข้อมูลโอกาสในการได้รับ Aurorian\n\nความน่าจะเป็นเริ่มต้นในการได้รับ Aurorian 6 ดาวจากการสรรหานี้คือ 2% หากคุณไม่สามารถสรรหา Aurorian 6 ดาวหลังจาก 50 ครั้งในการสรรหาติดต่อกัน ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวในครั้งถัดไปจะเพิ่มจาก 2% เป็น 4.5% หากคุณยังไม่สามารถสรรหา Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวในครั้งถัดไปจะเพิ่มจาก 4.5% เป็น 7% และเช่นกัน ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะเพิ่มขึ้น 2.5% จนถึง 100% หลังจากได้รับ Aurorian 6 ดาว ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะถูกรีเซ็ตเป็น 2%\nการสรรหานี้และการสรรหาหมุนตามกฎด้านบนทั้งหมด\n\nนี้หมายความว่าในการสรรหานี้หรือการสรรหาหมุน หากคุณไม่สามารถได้รับ Aurorian 6 ดาว ความน่าจะเป็นในการได้รับตัวละครดังกล่าวจะสะสม ความน่าจะเป็นสะสมนี้จะไม่ถูกล้างทิ้งในตอนท้ายของการสรรหานี้หรือการสรรหาหมุน และจะถือไปสู่การสรรหาหมุนถัดไปหรือการสรรหาแนะนำอื่น ๆ สมมุติว่ามีการสรรหาหมุนหลายครั้งที่ทำงานพร้อมกัน ในกรณีนั้น ความน่าจะเป็นนี้จะสะสมและใช้ร่วมกัน\nโปรดทราบว่ากลไกเพิ่มความน่าจะเป็นของการสรรหาประเภทต่างๆเป็นอิสระต่อกัน\nเมื่อคุณได้รับ Aurorian 6 ดาวจากการสรรหาในระยะเวลาจำกัดใด ๆ ความน่าจะเป็นในการได้รับ Aurorian 6 ดาวจะถูกรีเซ็ตเป็น 2%\n\nการสรรหานี้ไม่มีกลไกการรับประกัน และไม่ส่งผลกระทบต่อกลไกการรับประกันในการสรรหาอื่น ๆ",
  str_draw_card_pool_detail_sub_desc50047_2 = "ออโรเรียนที่สามารถอัญเชิญได้ทั้งหมด\nออโรเรียน 6 ดาว: 2.0%\nแอกเซลิอา/ยิงเกิล/บาร์ตัน: ดาบสำแดงเดช/เชอวาน\nออโรเรียน 5 ดาว: 9.5%\nเนเมซิส/บาร์ตัน/ฟิลิชี/คอร์ดี้/เบนนี่กับคุโระ/วิเวียน/ซีเอล\nออโรเรียน 4 ดาว: 33.0%\nแอนเซีย/แชนดรา/โจลา/ลิลเลียม\nออโรเรียน 3 ดาว: 55.5%\nยูนิเมต/ไวท์ดวาร์ฟ/โซยา",
  str_draw_card_pool_detail_sub_desc60009_1 = "การอัญเชิญเอ็กซ์คลูซีฟครั้งนี้มีออโรเรียนพิเศษเฉพาะเวลา จะเปิดเฉพาะในช่วงเวลาที่กำหนด และสามารถใช้สตาร์แฟลร์พิเศษในการอัญเชิญ ออโรเรียนสำหรับแบนเนอร์การอัญเชิญครั้งนี้คือออโรเรียน 6 ดาว <color=#ffbb00>เบธเลเฮม</color> เมื่ออัญเชิญออโรเรียน 6 ดาว คุณจะมีโอกาส 50% ในการอัญเชิญ <color=#ffbb00>เบธเลเฮม</color> ตัวละครนี้จะไม่ปรากฏในการอัญเชิญประเภทอื่น\n\nรายละเอียดกฎการอัญเชิญเอ็กซ์คลูซีฟดังนี้:\n\n- ออโรเรียน 5 ดาวจะได้รับการรับประกันภายใน 10 การอัญเชิญแรกของคุณ\n\n- ออโรเรียนนี้สามารถอัญเชิญได้เฉพาะจาก <color=#ffbb00>การอัญเชิญเอ็กซ์คลูซีฟ</color> และจะไม่ถูกเพิ่มเข้าไปในรายชื่อตัวละครที่สามารถได้รับในการอัญเชิญประเภทอื่น\n\n- กลไกเพิ่มความน่าจะเป็นของออโรเรียน 6 ดาว: ความน่าจะเป็นเริ่มต้นในการได้รับออโรเรียน 6 ดาวจากการอัญเชิญนี้คือ <color=#ffbb00>2%</color> หากคุณไม่สามารถอัญเชิญออโรเรียน 6 ดาวหลังจาก <color=#ffbb00>50</color> การอัญเชิญติดต่อกัน ความน่าจะเป็นในการได้รับออโรเรียน 6 ดาวในครั้งถัดไปจะเพิ่มจาก <color=#ffbb00>2%</color> เป็น <color=#ffbb00>4.5%</color> หากคุณยังไม่สามารถอัญเชิญออโรเรียน 6 ดาว ความน่าจะเป็นในการได้รับออโรเรียน 6 ดาวในครั้งถัดไปจะเพิ่มจาก <color=#ffbb00>4.5%</color> เป็น <color=#ffbb00>7%</color> และเช่นกัน ความน่าจะเป็นในการได้รับออโรเรียน 6 ดาวจะเพิ่มขึ้น <color=#ffbb00>2.5%</color> จนถึง <color=#ffbb00>100%</color> หลังจากได้รับออโรเรียน 6 ดาว ความน่าจะเป็นในการได้รับออโรเรียน 6 ดาวจะถูกรีเซ็ตเป็น <color=#ffbb00>2%</color>\n\n- กลไกการรับประกัน: ในการอัญเชิญเอ็กซ์คลูซีฟ หากไม่ได้รับออโรเรียน 6 ดาวที่โดดเด่นในการอัญเชิญนี้ภายใน <color=#ffbb00>2</color> ครั้งติดต่อกัน ออโรเรียน 6 ดาวถัดไปที่ได้รับจากการอัญเชิญนี้จะ <color=#ffbb00>รับประกัน</color> ว่าเป็นออโรเรียน 6 ดาวที่โดดเด่น ทุกครั้งที่ได้รับออโรเรียน 6 ดาวที่โดดเด่น กลไกการรับประกันจะถูกรีเซ็ตและคำนวณใหม่\n\nหมายเหตุ: การเพิ่มความน่าจะเป็นและกลไกการรับประกันของการอัญเชิญเอ็กซ์คลูซีฟนี้เป็นอิสระจากการเพิ่มความน่าจะเป็นและกลไกการรับประกันของการอัญเชิญประเภทอื่น ความน่าจะเป็นที่เพิ่มขึ้นและกลไกการรับประกันของราชินีแห่งเหนือใช้เฉพาะในช่วง